package main

import "fmt"

type Counter struct{ n int }

func (c Counter) IncCopy()  { c.n++ } // mutates a COPY — lost on return
func (c *Counter) IncReal() { c.n++ } // mutates the ORIGINAL — persists

func main() {
	c := Counter{}
	c.IncCopy() // no lasting effect
	fmt.Println("after IncCopy:", c.n) // 0
	c.IncReal() // Go auto-takes &c; mutation sticks
	fmt.Println("after IncReal:", c.n) // 1
}
